//! Command line definition, parsing and help rendering.
//!
//! The layout of the generated help/usage/error text intentionally mirrors what
//! the released binary emits, so the renderer below re-implements the column
//! alignment and wrapping rules rather than storing pre-rendered blobs.

pub const VERSION: &str = "1.0.0-rc.1";
pub const CRATE_NAME: &str = "rustowl";

/// Width used for wrapping help output when the terminal size is unknown.
const DEFAULT_TERM_WIDTH: usize = 100;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ArgKind {
    /// A `--flag` that takes no value.
    Flag,
    /// A `--opt <value>` that takes exactly one value.
    Opt,
    /// A bare positional argument.
    Positional,
}

#[derive(Clone)]
pub struct Arg {
    pub id: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub kind: ArgKind,
    pub value_name: &'static str,
    pub help: &'static str,
    pub long_help: Option<&'static str>,
    /// `-q` may be repeated; rendered as `--quiet...`.
    pub multiple: bool,
    pub required: bool,
    /// `(value, description)` pairs shown in long help / completions.
    pub possible_values: &'static [(&'static str, &'static str)],
    /// Whether shells should complete this value as a filesystem path.
    pub path_value: bool,
}

impl Arg {
    const fn base(id: &'static str) -> Arg {
        Arg {
            id,
            short: None,
            long: None,
            kind: ArgKind::Flag,
            value_name: "",
            help: "",
            long_help: None,
            multiple: false,
            required: false,
            possible_values: &[],
            path_value: false,
        }
    }

    pub fn takes_value(&self) -> bool {
        matches!(self.kind, ArgKind::Opt)
    }

    pub fn is_positional(&self) -> bool {
        matches!(self.kind, ArgKind::Positional)
    }

    /// `-V, --version` / `    --stdio` / `  [path]`
    fn flag_column(&self) -> String {
        if self.is_positional() {
            return self.usage_token();
        }
        let mut s = String::new();
        match self.short {
            Some(c) => {
                s.push('-');
                s.push(c);
                if self.long.is_some() {
                    s.push_str(", ");
                }
            }
            None => {
                if self.long.is_some() {
                    s.push_str("    ");
                }
            }
        }
        if let Some(l) = self.long {
            s.push_str("--");
            s.push_str(l);
        }
        if self.multiple {
            s.push_str("...");
        }
        if self.takes_value() {
            s.push_str(&format!(" <{}>", self.value_name));
        }
        s
    }

    fn usage_token(&self) -> String {
        if self.required {
            format!("<{}>", self.value_name)
        } else {
            format!("[{}]", self.value_name)
        }
    }
}

#[derive(Clone)]
pub struct Cmd {
    pub name: &'static str,
    pub about: &'static str,
    pub args: Vec<Arg>,
    pub subs: Vec<Cmd>,
    /// True for the automatically generated `help` subcommand.
    pub is_help_stub: bool,
}

impl Cmd {
    fn new(name: &'static str, about: &'static str) -> Cmd {
        Cmd {
            name,
            about,
            args: Vec::new(),
            subs: Vec::new(),
            is_help_stub: false,
        }
    }

    pub fn find_sub(&self, name: &str) -> Option<&Cmd> {
        self.subs.iter().find(|c| c.name == name)
    }

    pub fn has_subs(&self) -> bool {
        !self.subs.is_empty()
    }

    fn positionals(&self) -> Vec<&Arg> {
        self.args.iter().filter(|a| a.is_positional()).collect()
    }

    fn options(&self) -> Vec<&Arg> {
        self.args.iter().filter(|a| !a.is_positional()).collect()
    }

    /// Long help is used when some argument carries extra documentation.
    fn needs_long_layout(&self) -> bool {
        self.args
            .iter()
            .any(|a| a.long_help.is_some() || !a.possible_values.is_empty())
    }
}

// ---------------------------------------------------------------------------
// The command tree
// ---------------------------------------------------------------------------

const HELP_ABOUT: &str = "Print this message or the help of the given subcommand(s)";

fn help_arg() -> Arg {
    Arg {
        short: Some('h'),
        long: Some("help"),
        help: "Print help",
        ..Arg::base("help")
    }
}

fn help_arg_with_long() -> Arg {
    Arg {
        short: Some('h'),
        long: Some("help"),
        help: "Print help (see more with '--help')",
        long_help: Some("Print help (see a summary with '-h')"),
        ..Arg::base("help")
    }
}

/// The automatically generated `help` subcommand for `parent`.
///
/// Its children mirror the parent's subcommands; deeper levels drop their own
/// generated `help` entry.
fn build_help_sub(subs: &[Cmd]) -> Cmd {
    let mut help = Cmd::new("help", HELP_ABOUT);
    help.is_help_stub = true;
    help.subs = subs.iter().map(mirror_sub).collect();
    help
}

fn mirror_sub(cmd: &Cmd) -> Cmd {
    let mut c = Cmd::new(cmd.name, cmd.about);
    c.is_help_stub = true;
    c.subs = cmd
        .subs
        .iter()
        .filter(|s| !s.is_help_stub)
        .map(mirror_sub)
        .collect();
    c
}

pub fn root() -> Cmd {
    let mut check = Cmd::new("check", "Check availability");
    check.args = vec![
        Arg {
            long: Some("all-targets"),
            help: "Run the check for all targets instead of current only",
            ..Arg::base("all_targets")
        },
        Arg {
            long: Some("all-features"),
            help: "Run the check for all features instead of the current active ones only",
            ..Arg::base("all_features")
        },
        help_arg(),
        Arg {
            kind: ArgKind::Positional,
            value_name: "path",
            help: "The path of a file or directory to check availability",
            path_value: true,
            ..Arg::base("path")
        },
    ];

    let mut clean = Cmd::new("clean", "Remove artifacts from the target directory");
    clean.args = vec![help_arg()];

    let mut install = Cmd::new("install", "Install the toolchain");
    install.args = vec![
        Arg {
            long: Some("path"),
            kind: ArgKind::Opt,
            value_name: "path",
            help: "Runtime directory path to install RustOwl toolchain",
            path_value: true,
            ..Arg::base("path")
        },
        Arg {
            long: Some("skip-rustowl-toolchain"),
            help: "Install Rust toolchain only",
            ..Arg::base("skip_rustowl_toolchain")
        },
        help_arg(),
    ];

    let mut uninstall = Cmd::new("uninstall", "Uninstall the toolchain");
    uninstall.args = vec![help_arg()];

    let mut toolchain = Cmd::new("toolchain", "Install or uninstall the toolchain");
    toolchain.args = vec![help_arg()];
    toolchain.subs = vec![install, uninstall];
    let tc_help = build_help_sub(&toolchain.subs);
    toolchain.subs.push(tc_help);

    let mut completions = Cmd::new("completions", "Generate shell completions");
    completions.args = vec![
        help_arg_with_long(),
        Arg {
            kind: ArgKind::Positional,
            value_name: "SHELL",
            required: true,
            help: "The shell to generate completions for",
            possible_values: SHELLS,
            ..Arg::base("shell")
        },
    ];

    let mut root = Cmd::new(CRATE_NAME, "");
    root.args = vec![
        Arg {
            short: Some('V'),
            long: Some("version"),
            help: "Print version",
            ..Arg::base("version")
        },
        Arg {
            short: Some('q'),
            long: Some("quiet"),
            help: "Suppress output",
            multiple: true,
            ..Arg::base("quiet")
        },
        Arg {
            long: Some("stdio"),
            help: "Use stdio to communicate with the LSP server",
            ..Arg::base("stdio")
        },
        help_arg(),
    ];
    root.subs = vec![check, clean, toolchain, completions];
    let root_help = build_help_sub(&root.subs);
    root.subs.push(root_help);
    root
}

pub const SHELLS: &[(&str, &str)] = &[
    ("bash", "Bourne Again `SHell` (bash)"),
    ("elvish", "Elvish shell"),
    ("fish", "Friendly Interactive `SHell` (fish)"),
    ("powershell", "`PowerShell`"),
    ("zsh", "Z `SHell` (zsh)"),
    ("nushell", "Nushell"),
];

// ---------------------------------------------------------------------------
// Help rendering
// ---------------------------------------------------------------------------

fn term_width() -> usize {
    DEFAULT_TERM_WIDTH
}

fn usage_line(bin: &str, path: &[&str], cmd: &Cmd) -> String {
    let mut s = String::from("Usage: ");
    s.push_str(bin);
    for p in path {
        s.push(' ');
        s.push_str(p);
    }
    let opts = cmd.options();
    // clap collapses several options into `[OPTIONS]`; a lone `-h/--help`
    // is not advertised in the usage line at all.
    let visible: Vec<&&Arg> = opts.iter().filter(|a| a.id != "help").collect();
    if visible.len() == 1 {
        let a = visible[0];
        let mut token = String::from("[");
        if let Some(l) = a.long {
            token.push_str("--");
            token.push_str(l);
        } else if let Some(c) = a.short {
            token.push('-');
            token.push(c);
        }
        if a.takes_value() {
            token.push_str(&format!(" <{}>", a.value_name));
        }
        token.push(']');
        s.push(' ');
        s.push_str(&token);
    } else if !visible.is_empty() {
        s.push_str(" [OPTIONS]");
    }
    for p in cmd.positionals() {
        s.push(' ');
        s.push_str(&p.usage_token());
    }
    if cmd.has_subs() {
        s.push_str(" [COMMAND]");
        if cmd.is_help_stub {
            s.push_str("...");
        }
    }
    s
}

/// `clap`'s two-column layout: entries are padded to the widest key plus two
/// spaces, and descriptions wrap to that column.
fn write_two_column(out: &mut String, rows: &[(String, String)], width: usize) {
    let key_width = rows.iter().map(|(k, _)| k.chars().count()).max().unwrap_or(0);
    let desc_col = 2 + key_width + 2;
    for (key, desc) in rows {
        out.push_str("  ");
        out.push_str(key);
        if desc.is_empty() {
            out.push('\n');
            continue;
        }
        let pad = key_width - key.chars().count() + 2;
        out.push_str(&" ".repeat(pad));
        let avail = width.saturating_sub(desc_col).max(10);
        let lines = wrap(desc, avail);
        for (i, line) in lines.iter().enumerate() {
            if i > 0 {
                out.push_str(&" ".repeat(desc_col));
            }
            out.push_str(line);
            out.push('\n');
        }
    }
}

fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut current = String::new();
    for word in text.split(' ') {
        if current.is_empty() {
            current.push_str(word);
        } else if current.chars().count() + 1 + word.chars().count() <= width {
            current.push(' ');
            current.push_str(word);
        } else {
            lines.push(std::mem::take(&mut current));
            current.push_str(word);
        }
    }
    lines.push(current);
    lines
}

pub fn render_help(bin: &str, path: &[&str], cmd: &Cmd, long: bool) -> String {
    let width = term_width();
    let use_long = long && cmd.needs_long_layout();
    let mut out = String::new();
    if !cmd.about.is_empty() {
        out.push_str(cmd.about);
        out.push_str("\n\n");
    }
    out.push_str(&usage_line(bin, path, cmd));
    out.push_str("\n");

    if use_long {
        render_long_sections(&mut out, cmd, width);
    } else {
        render_short_sections(&mut out, cmd, width);
    }
    out
}

fn short_help_of(arg: &Arg) -> String {
    let mut help = arg.help.to_string();
    if !arg.possible_values.is_empty() {
        let values: Vec<&str> = arg.possible_values.iter().map(|(v, _)| *v).collect();
        if !help.is_empty() {
            help.push(' ');
        }
        help.push_str(&format!("[possible values: {}]", values.join(", ")));
    }
    help
}

fn render_short_sections(out: &mut String, cmd: &Cmd, width: usize) {
    let positionals = cmd.positionals();
    if !positionals.is_empty() {
        out.push_str("\nArguments:\n");
        let rows: Vec<(String, String)> = positionals
            .iter()
            .map(|a| (a.flag_column(), short_help_of(a)))
            .collect();
        write_two_column(out, &rows, width);
    }
    if cmd.has_subs() {
        out.push_str("\nCommands:\n");
        let rows: Vec<(String, String)> = cmd
            .subs
            .iter()
            .map(|c| (c.name.to_string(), c.about.to_string()))
            .collect();
        write_two_column(out, &rows, width);
    }
    let options = cmd.options();
    if !options.is_empty() {
        out.push_str("\nOptions:\n");
        let rows: Vec<(String, String)> = options
            .iter()
            .map(|a| (a.flag_column(), short_help_of(a)))
            .collect();
        write_two_column(out, &rows, width);
    }
}

/// clap's "next line help" layout, used when an argument has long help text.
fn render_long_sections(out: &mut String, cmd: &Cmd, width: usize) {
    const INDENT: &str = "          ";
    let emit = |out: &mut String, args: &[&Arg]| {
        for arg in args {
            out.push_str("  ");
            out.push_str(&arg.flag_column());
            out.push('\n');
            let help = arg.long_help.unwrap_or(arg.help);
            if !help.is_empty() {
                for line in help.split('\n') {
                    for wrapped in wrap(line, width.saturating_sub(INDENT.len()).max(10)) {
                        out.push_str(INDENT);
                        out.push_str(&wrapped);
                        out.push('\n');
                    }
                }
            }
            if !arg.possible_values.is_empty() {
                out.push('\n');
                out.push_str(INDENT);
                out.push_str("Possible values:\n");
                let key_width = arg
                    .possible_values
                    .iter()
                    .map(|(v, _)| v.chars().count())
                    .max()
                    .unwrap_or(0);
                for (value, desc) in arg.possible_values {
                    out.push_str(INDENT);
                    out.push_str("- ");
                    out.push_str(value);
                    out.push(':');
                    let pad = key_width - value.chars().count() + 1;
                    out.push_str(&" ".repeat(pad));
                    out.push_str(desc);
                    out.push('\n');
                }
            }
            out.push('\n');
        }
    };

    let positionals = cmd.positionals();
    if !positionals.is_empty() {
        out.push_str("\nArguments:\n");
        emit(out, &positionals);
        // the trailing blank line of the last entry doubles as the separator
        while out.ends_with("\n\n") {
            out.pop();
        }
    }
    if cmd.has_subs() {
        out.push_str("\nCommands:\n");
        let rows: Vec<(String, String)> = cmd
            .subs
            .iter()
            .map(|c| (c.name.to_string(), c.about.to_string()))
            .collect();
        write_two_column(out, &rows, width);
    }
    let options = cmd.options();
    if !options.is_empty() {
        out.push_str("\nOptions:\n");
        emit(out, &options);
        while out.ends_with("\n\n") {
            out.pop();
        }
    }
}

pub fn render_usage_only(bin: &str, path: &[&str], cmd: &Cmd) -> String {
    usage_line(bin, path, cmd)
}

