//! Shell completion script generation for the six supported shells.
//!
//! Each generator walks the command tree from `cli::root()`; nothing is
//! pre-rendered. The scripts always refer to the crate name (`rustowl`) rather
//! than to `argv[0]`.

use crate::cli::{Arg, ArgKind, Cmd};

pub const SHELL_NAMES: &[&str] = &["bash", "elvish", "fish", "powershell", "zsh", "nushell"];

pub fn generate(shell: &str, root: &Cmd) -> Option<String> {
    match shell {
        "bash" => Some(bash(root)),
        "elvish" => Some(elvish(root)),
        "fish" => Some(fish(root)),
        "powershell" => Some(powershell(root)),
        "zsh" => Some(zsh(root)),
        "nushell" => Some(nushell(root)),
        _ => None,
    }
}

/// A command together with the path of names leading to it.
struct Node<'a> {
    path: Vec<&'a str>,
    cmd: &'a Cmd,
}

/// Depth-first pre-order walk in declaration order.
fn walk<'a>(root: &'a Cmd) -> Vec<Node<'a>> {
    let mut out = Vec::new();
    fn rec<'a>(cmd: &'a Cmd, path: Vec<&'a str>, out: &mut Vec<Node<'a>>) {
        out.push(Node {
            path: path.clone(),
            cmd,
        });
        for sub in &cmd.subs {
            let mut p = path.clone();
            p.push(sub.name);
            rec(sub, p, out);
        }
    }
    rec(root, vec![root.name], &mut out);
    out
}

fn shorts(cmd: &Cmd) -> Vec<&Arg> {
    cmd.args
        .iter()
        .filter(|a| !a.is_positional() && a.short.is_some())
        .collect()
}

fn longs(cmd: &Cmd) -> Vec<&Arg> {
    cmd.args
        .iter()
        .filter(|a| !a.is_positional() && a.long.is_some())
        .collect()
}

fn positionals(cmd: &Cmd) -> Vec<&Arg> {
    cmd.args.iter().filter(|a| a.is_positional()).collect()
}

fn options(cmd: &Cmd) -> Vec<&Arg> {
    cmd.args.iter().filter(|a| !a.is_positional()).collect()
}

// ---------------------------------------------------------------------------
// bash
// ---------------------------------------------------------------------------

fn bash_id(path: &[&str]) -> String {
    path.join("__")
}

fn bash(root: &Cmd) -> String {
    let nodes = walk(root);
    let mut out = String::new();
    let fname = format!("_{}", root.name);

    out.push_str(&format!("{fname}() {{\n"));
    out.push_str(
        "    local i cur prev opts cmd\n\
         \x20   COMPREPLY=()\n\
         \x20   if [[ \"${BASH_VERSINFO[0]}\" -ge 4 ]]; then\n\
         \x20       cur=\"$2\"\n\
         \x20   else\n\
         \x20       cur=\"${COMP_WORDS[COMP_CWORD]}\"\n\
         \x20   fi\n\
         \x20   prev=\"$3\"\n\
         \x20   cmd=\"\"\n\
         \x20   opts=\"\"\n\n\
         \x20   for i in \"${COMP_WORDS[@]:0:COMP_CWORD}\"\n\
         \x20   do\n\
         \x20       case \"${cmd},${i}\" in\n",
    );
    out.push_str(&format!(
        "            \",$1\")\n                cmd=\"{}\"\n                ;;\n",
        root.name
    ));

    // Transitions, sorted by the literal case pattern.
    let mut transitions: Vec<(String, String)> = Vec::new();
    for node in &nodes {
        if node.cmd.subs.is_empty() {
            continue;
        }
        let parent = bash_id(&node.path);
        for sub in &node.cmd.subs {
            let mut p = node.path.clone();
            p.push(sub.name);
            transitions.push((format!("{parent},{}", sub.name), bash_id(&p)));
        }
    }
    transitions.sort();
    for (pattern, target) in transitions {
        out.push_str(&format!(
            "            {pattern})\n                cmd=\"{target}\"\n                ;;\n"
        ));
    }
    out.push_str("            *)\n                ;;\n        esac\n    done\n\n");

    out.push_str("    case \"${cmd}\" in\n");
    let mut blocks: Vec<(String, &Node)> = nodes
        .iter()
        .map(|n| (bash_id(&n.path), n))
        .collect();
    blocks.sort_by(|a, b| a.0.cmp(&b.0));
    for (id, node) in blocks {
        let cmd = node.cmd;
        let mut opts: Vec<String> = Vec::new();
        for a in shorts(cmd) {
            opts.push(format!("-{}", a.short.unwrap()));
        }
        for a in longs(cmd) {
            opts.push(format!("--{}", a.long.unwrap()));
        }
        for p in positionals(cmd) {
            if p.possible_values.is_empty() {
                opts.push(if p.required {
                    format!("<{}>", p.value_name)
                } else {
                    format!("[{}]", p.value_name)
                });
            } else {
                for (v, _) in p.possible_values {
                    opts.push(v.to_string());
                }
            }
        }
        for sub in &cmd.subs {
            opts.push(sub.name.to_string());
        }
        out.push_str(&format!("        {id})\n"));
        out.push_str(&format!("            opts=\"{}\"\n", opts.join(" ")));
        out.push_str(&format!(
            "            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq {} ]] ; then\n",
            node.path.len()
        ));
        out.push_str(
            "                COMPREPLY=( $(compgen -W \"${opts}\" -- \"${cur}\") )\n\
             \x20               return 0\n            fi\n",
        );
        out.push_str("            case \"${prev}\" in\n");
        for a in options(cmd) {
            if !a.takes_value() {
                continue;
            }
            let name = match a.long {
                Some(l) => format!("--{l}"),
                None => format!("-{}", a.short.unwrap()),
            };
            out.push_str(&format!("                {name})\n"));
            if a.path_value {
                out.push_str("                    COMPREPLY=($(compgen -f \"${cur}\"))\n");
            } else {
                out.push_str("                    COMPREPLY=($(compgen -f \"${cur}\"))\n");
            }
            out.push_str("                    return 0\n                    ;;\n");
        }
        out.push_str("                *)\n                    COMPREPLY=()\n                    ;;\n");
        out.push_str("            esac\n");
        out.push_str(
            "            COMPREPLY=( $(compgen -W \"${opts}\" -- \"${cur}\") )\n\
             \x20           return 0\n            ;;\n",
        );
    }
    out.push_str("    esac\n}\n\n");
    out.push_str(&format!(
        "if [[ \"${{BASH_VERSINFO[0]}}\" -eq 4 && \"${{BASH_VERSINFO[1]}}\" -ge 4 || \
         \"${{BASH_VERSINFO[0]}}\" -gt 4 ]]; then\n\
         \x20   complete -F {fname} -o nosort -o bashdefault -o default {}\n\
         else\n\
         \x20   complete -F {fname} -o bashdefault -o default {}\n\
         fi\n",
        root.name, root.name
    ));
    out
}

// ---------------------------------------------------------------------------
// elvish
// ---------------------------------------------------------------------------

fn elvish_escape(s: &str) -> String {
    s.replace('\'', "''")
}

fn elvish(root: &Cmd) -> String {
    let mut out = String::new();
    out.push_str("use builtin;\nuse str;\n\n");
    out.push_str(&format!(
        "set edit:completion:arg-completer[{}] = {{|@words|\n",
        root.name
    ));
    out.push_str(
        "    fn spaces {|n|\n\
         \x20       builtin:repeat $n ' ' | str:join ''\n\
         \x20   }\n\
         \x20   fn cand {|text desc|\n\
         \x20       edit:complex-candidate $text &display=$text' '(spaces (- 14 \
         (wcswidth $text)))$desc\n\
         \x20   }\n",
    );
    out.push_str(&format!("    var command = '{}'\n", root.name));
    out.push_str(
        "    for word $words[1..-1] {\n\
         \x20       if (str:has-prefix $word '-') {\n\
         \x20           break\n\
         \x20       }\n\
         \x20       set command = $command';'$word\n\
         \x20   }\n\
         \x20   var completions = [\n",
    );
    for node in walk(root) {
        out.push_str(&format!("        &'{}'= {{\n", node.path.join(";")));
        for a in options(node.cmd) {
            let desc = elvish_escape(a.help);
            if let Some(c) = a.short {
                out.push_str(&format!("            cand -{c} '{desc}'\n"));
            }
            if let Some(l) = a.long {
                out.push_str(&format!("            cand --{l} '{desc}'\n"));
            }
        }
        for sub in &node.cmd.subs {
            out.push_str(&format!(
                "            cand {} '{}'\n",
                sub.name,
                elvish_escape(sub.about)
            ));
        }
        out.push_str("        }\n");
    }
    out.push_str("    ]\n    $completions[$command]\n}\n");
    out
}

// ---------------------------------------------------------------------------
// fish
// ---------------------------------------------------------------------------

fn fish_escape(s: &str) -> String {
    s.replace('\\', "\\\\").replace('\'', "\\'")
}

fn fish(root: &Cmd) -> String {
    let name = root.name;
    let mut out = String::new();
    out.push_str(
        "# Print an optspec for argparse to handle cmd's options that are independent of any \
         subcommand.\n",
    );
    out.push_str(&format!("function __fish_{name}_global_optspecs\n"));
    let mut specs: Vec<String> = Vec::new();
    for a in options(root) {
        let mut s = String::new();
        if let Some(c) = a.short {
            s.push(c);
            s.push('/');
        }
        if let Some(l) = a.long {
            s.push_str(l);
        }
        if a.takes_value() {
            s.push('=');
        }
        specs.push(s);
    }
    out.push_str(&format!("\tstring join \\n {}\nend\n\n", specs.join(" ")));
    out.push_str(&format!(
        "function __fish_{name}_needs_command\n\
         \t# Figure out if the current invocation already has a command.\n\
         \tset -l cmd (commandline -opc)\n\
         \tset -e cmd[1]\n\
         \targparse -s (__fish_{name}_global_optspecs) -- $cmd 2>/dev/null\n\
         \tor return\n\
         \tif set -q argv[1]\n\
         \t\t# Also print the command, so this can be used to figure out what it is.\n\
         \t\techo $argv[1]\n\
         \t\treturn 1\n\
         \tend\n\
         \treturn 0\n\
         end\n\n\
         function __fish_{name}_using_subcommand\n\
         \tset -l cmd (__fish_{name}_needs_command)\n\
         \ttest -z \"$cmd\"\n\
         \tand return 1\n\
         \tcontains -- $cmd[1] $argv\n\
         end\n\n"
    ));

    for node in walk(root) {
        let condition = if node.path.len() == 1 {
            format!("__fish_{name}_needs_command")
        } else {
            let mut c = format!("__fish_{name}_using_subcommand {}", node.path[1]);
            // Deeper levels are disambiguated with __fish_seen_subcommand_from.
            for (i, seg) in node.path.iter().enumerate().skip(2) {
                let _ = i;
                c.push_str(&format!("; and __fish_seen_subcommand_from {seg}"));
            }
            if !node.cmd.subs.is_empty() && node.path.len() >= 2 {
                let names: Vec<&str> = node.cmd.subs.iter().map(|s| s.name).collect();
                c.push_str(&format!(
                    "; and not __fish_seen_subcommand_from {}",
                    names.join(" ")
                ));
            }
            c
        };
        for a in options(node.cmd) {
            let mut line = format!("complete -c {name} -n \"{condition}\"");
            if let Some(c) = a.short {
                line.push_str(&format!(" -s {c}"));
            }
            if let Some(l) = a.long {
                line.push_str(&format!(" -l {l}"));
            }
            if !a.help.is_empty() {
                line.push_str(&format!(" -d '{}'", fish_escape(a.help)));
            }
            if a.takes_value() {
                line.push_str(" -r");
                if a.path_value {
                    line.push_str(" -F");
                }
            }
            out.push_str(&line);
            out.push('\n');
        }
        for sub in &node.cmd.subs {
            out.push_str(&format!(
                "complete -c {name} -n \"{condition}\" -f -a \"{}\" -d '{}'\n",
                sub.name,
                fish_escape(sub.about)
            ));
        }
    }
    out
}

// ---------------------------------------------------------------------------
// powershell
// ---------------------------------------------------------------------------

fn ps_escape(s: &str) -> String {
    s.replace('\'', "''")
}

fn powershell(root: &Cmd) -> String {
    let name = root.name;
    let mut out = String::new();
    out.push_str(
        "\nusing namespace System.Management.Automation\n\
         using namespace System.Management.Automation.Language\n\n",
    );
    out.push_str(&format!(
        "Register-ArgumentCompleter -Native -CommandName '{name}' -ScriptBlock {{\n\
         \x20   param($wordToComplete, $commandAst, $cursorPosition)\n\n\
         \x20   $commandElements = $commandAst.CommandElements\n\
         \x20   $command = @(\n\
         \x20       '{name}'\n\
         \x20       for ($i = 1; $i -lt $commandElements.Count; $i++) {{\n\
         \x20           $element = $commandElements[$i]\n\
         \x20           if ($element -isnot [StringConstantExpressionAst] -or\n\
         \x20               $element.StringConstantType -ne [StringConstantType]::BareWord -or\n\
         \x20               $element.Value.StartsWith('-') -or\n\
         \x20               $element.Value -eq $wordToComplete) {{\n\
         \x20               break\n\
         \x20       }}\n\
         \x20       $element.Value\n\
         \x20   }}) -join ';'\n\n\
         \x20   $completions = @(switch ($command) {{\n"
    ));
    for node in walk(root) {
        out.push_str(&format!("        '{}' {{\n", node.path.join(";")));
        for a in options(node.cmd) {
            let desc = ps_escape(a.help);
            if let Some(c) = a.short {
                // clap pads a bare `-V` style completion text with one space.
                let display = if a.long.is_some() && a.short == Some('V') {
                    format!("-{c} ")
                } else {
                    format!("-{c}")
                };
                out.push_str(&format!(
                    "            [CompletionResult]::new('-{c}', '{display}', \
                     [CompletionResultType]::ParameterName, '{desc}')\n"
                ));
            }
            if let Some(l) = a.long {
                out.push_str(&format!(
                    "            [CompletionResult]::new('--{l}', '--{l}', \
                     [CompletionResultType]::ParameterName, '{desc}')\n"
                ));
            }
        }
        for sub in &node.cmd.subs {
            out.push_str(&format!(
                "            [CompletionResult]::new('{}', '{}', \
                 [CompletionResultType]::ParameterValue, '{}')\n",
                sub.name,
                sub.name,
                ps_escape(sub.about)
            ));
        }
        out.push_str("            break\n        }\n");
    }
    out.push_str(
        "    })\n\n\
         \x20   $completions.Where{ $_.CompletionText -like \"$wordToComplete*\" } |\n\
         \x20       Sort-Object -Property ListItemText\n\
         }\n",
    );
    out
}

// ---------------------------------------------------------------------------
// zsh
// ---------------------------------------------------------------------------

fn zsh_escape_bracket(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('[', "\\[")
        .replace(']', "\\]")
        .replace('\'', "'\\''")
        .replace(':', "\\:")
        .replace('$', "\\$")
        .replace('`', "\\`")
}

fn zsh_id(path: &[&str]) -> String {
    path.join("__")
}

fn zsh(root: &Cmd) -> String {
    let name = root.name;
    let mut out = String::new();
    out.push_str(&format!("#compdef {name}\n\n"));
    out.push_str("autoload -U is-at-least\n\n");
    out.push_str(&format!("_{name}() {{\n"));
    out.push_str(
        "    typeset -A opt_args\n\
         \x20   typeset -a _arguments_options\n\
         \x20   local ret=1\n\n\
         \x20   if is-at-least 5.2; then\n\
         \x20       _arguments_options=(-s -S -C)\n\
         \x20   else\n\
         \x20       _arguments_options=(-s -C)\n\
         \x20   fi\n\n\
         \x20   local context curcontext=\"$curcontext\" state line\n",
    );
    zsh_command(&mut out, root, &[root.name], 0, true);
    out.push_str("}\n\n");

    // `_<cmd>_commands` helper functions, sorted by function name.
    let mut helpers: Vec<(String, String)> = Vec::new();
    for node in walk(root) {
        let id = zsh_id(&node.path);
        let fname = format!("_{id}_commands");
        let mut body = String::new();
        body.push_str(&format!("(( $+functions[{fname}] )) ||\n{fname}() {{\n"));
        if node.cmd.subs.is_empty() {
            body.push_str("    local commands; commands=()\n");
        } else {
            body.push_str("    local commands; commands=(\n");
            for sub in &node.cmd.subs {
                body.push_str(&format!(
                    "'{}:{}' \\\n",
                    sub.name,
                    zsh_escape_desc(sub.about)
                ));
            }
            body.push_str("    )\n");
        }
        body.push_str(&format!(
            "    _describe -t commands '{} commands' commands \"$@\"\n}}\n",
            node.path.join(" ")
        ));
        helpers.push((fname, body));
    }
    helpers.sort_by(|a, b| a.0.cmp(&b.0));
    for (_, body) in helpers {
        out.push_str(&body);
    }

    out.push_str(&format!(
        "\nif [ \"$funcstack[1]\" = \"_{name}\" ]; then\n\
         \x20   _{name} \"$@\"\n\
         else\n\
         \x20   compdef _{name} {name}\n\
         fi\n"
    ));
    out
}

fn zsh_escape_desc(s: &str) -> String {
    s.replace('\\', "\\\\").replace('\'', "'\\''")
}

fn zsh_arg_line(a: &Arg) -> Vec<String> {
    let mut lines = Vec::new();
    let desc = zsh_escape_bracket(a.help);
    let star = if a.multiple { "*" } else { "" };
    if a.takes_value() {
        if let Some(c) = a.short {
            lines.push(format!(
                "'{star}-{c}+[{desc}]:{}:_files'",
                a.value_name
            ));
        }
        if let Some(l) = a.long {
            lines.push(format!(
                "'{star}--{l}=[{desc}]:{}:_files'",
                a.value_name
            ));
        }
    } else {
        if let Some(c) = a.short {
            lines.push(format!("'{star}-{c}[{desc}]'"));
        }
        if let Some(l) = a.long {
            lines.push(format!("'{star}--{l}[{desc}]'"));
        }
    }
    lines
}

fn zsh_positional_line(a: &Arg) -> String {
    let desc = zsh_escape_bracket(a.help);
    if a.possible_values.is_empty() {
        let prefix = if a.required { ":" } else { "::" };
        format!(
            "'{prefix}{} -- {}:_files'",
            a.value_name.to_lowercase(),
            desc
        )
    } else {
        let mut s = format!("':{} -- {}:((", a.value_name.to_lowercase(), desc);
        let items: Vec<String> = a
            .possible_values
            .iter()
            .map(|(v, d)| format!("{v}\\:\"{}\"", zsh_escape_value_desc(d)))
            .collect();
        s.push_str(&items.join("\n"));
        s.push_str("))'");
        s
    }
}

fn zsh_escape_value_desc(s: &str) -> String {
    s.replace('\\', "\\\\").replace('`', "\\`")
}

fn zsh_command(out: &mut String, cmd: &Cmd, path: &[&str], depth: usize, is_root: bool) {
    out.push_str("_arguments \"${_arguments_options[@]}\" : \\\n");
    for a in options(cmd) {
        for line in zsh_arg_line(a) {
            out.push_str(&format!("{line} \\\n"));
        }
    }
    for p in positionals(cmd) {
        out.push_str(&format!("{} \\\n", zsh_positional_line(p)));
    }
    if cmd.has_subs() {
        out.push_str(&format!("\":: :_{}_commands\" \\\n", zsh_id(path)));
        out.push_str(&format!("\"*::: :->{}\" \\\n", path[path.len() - 1]));
    }
    out.push_str("&& ret=0\n");
    if cmd.has_subs() {
        if !is_root {
            out.push('\n');
        }
        let state = path[path.len() - 1];
        out.push_str("    case $state in\n");
        out.push_str(&format!("    ({state})\n"));
        out.push_str("        words=($line[1] \"${words[@]}\")\n");
        out.push_str("        (( CURRENT += 1 ))\n");
        out.push_str(&format!(
            "        curcontext=\"${{curcontext%:*:*}}:{}-command-$line[1]:\"\n",
            path.join("-")
        ));
        out.push_str("        case $line[1] in\n");
        for (i, sub) in cmd.subs.iter().enumerate() {
            let indent = if i == 0 { "            " } else { "" };
            out.push_str(&format!("{indent}({})\n", sub.name));
            let mut p = path.to_vec();
            p.push(sub.name);
            zsh_command(out, sub, &p, depth + 1, false);
            out.push_str(";;\n");
        }
        out.push_str("        esac\n    ;;\nesac\n");
    }
}

// ---------------------------------------------------------------------------
// nushell
// ---------------------------------------------------------------------------

fn nu_flag_text(a: &Arg) -> String {
    let mut s = String::new();
    if let Some(l) = a.long {
        s.push_str("--");
        s.push_str(l);
        if let Some(c) = a.short {
            s.push_str(&format!("({}{})", '-', c));
        }
    } else if let Some(c) = a.short {
        s.push_str(&format!("-{c}"));
    }
    if a.takes_value() {
        s.push_str(": ");
        s.push_str(if a.path_value { "path" } else { "string" });
    }
    s
}

fn nu_positional_text(a: &Arg, path: &[&str]) -> String {
    let name = a.value_name.to_lowercase();
    let optional = if a.required { "" } else { "?" };
    if !a.possible_values.is_empty() {
        format!(
            "{name}{optional}: string@\"nu-complete {} {name}\"",
            path.join(" ")
        )
    } else if a.path_value {
        format!("{name}{optional}: path")
    } else {
        format!("{name}{optional}: string")
    }
}

fn nushell(root: &Cmd) -> String {
    let nodes = walk(root);
    // Flags across the whole tree share one alignment column.
    let width = nodes
        .iter()
        .flat_map(|n| options(n.cmd))
        .map(|a| nu_flag_text(a).chars().count())
        .max()
        .unwrap_or(0)
        + 2;

    let mut out = String::new();
    out.push_str("module completions {\n\n");
    for node in &nodes {
        // value completers must be declared before the command that uses them
        for p in positionals(node.cmd) {
            if p.possible_values.is_empty() {
                continue;
            }
            out.push_str(&format!(
                "  def \"nu-complete {} {}\" [] {{\n    [ {} ]\n  }}\n\n",
                node.path.join(" "),
                p.value_name.to_lowercase(),
                p.possible_values
                    .iter()
                    .map(|(v, _)| format!("\"{v}\""))
                    .collect::<Vec<_>>()
                    .join(" ")
            ));
        }
        if !node.cmd.about.is_empty() {
            out.push_str(&format!("  # {}\n", node.cmd.about));
        }
        let decl = if node.path.len() == 1 {
            format!("  export extern {} [\n", node.path[0])
        } else {
            format!("  export extern \"{}\" [\n", node.path.join(" "))
        };
        out.push_str(&decl);
        for a in options(node.cmd) {
            let text = nu_flag_text(a);
            let pad = width.saturating_sub(text.chars().count()).max(1);
            out.push_str(&format!(
                "    {text}{}# {}\n",
                " ".repeat(pad),
                a.help
            ));
        }
        for p in positionals(node.cmd) {
            let text = nu_positional_text(p, &node.path);
            let pad = width.saturating_sub(text.chars().count()).max(1);
            out.push_str(&format!(
                "    {text}{}# {}\n",
                " ".repeat(pad),
                p.help
            ));
        }
        out.push_str("  ]\n\n");
    }
    out.push_str("}\n\nexport use completions *\n");
    out
}

