mod cli;
mod completions;
mod json;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let root = cli::root();
    if args.len() >= 3 && args[1] == "completions" {
        if let Some(s) = completions::generate(&args[2], &root) {
            print!("{s}");
        }
        return;
    }
    if args.len() >= 2 && args[1] == "help-dump" {
        let long = args.get(3).map(|s| s == "long").unwrap_or(false);
        let path: Vec<&str> = if args[2].is_empty() {
            vec![]
        } else {
            args[2].split(' ').collect()
        };
        let mut cmd = &root;
        for p in &path {
            cmd = cmd.find_sub(p).unwrap();
        }
        print!("{}", cli::render_help("executable", &path, cmd, long));
        return;
    }
    let _ = json::parse("null");
}

