1	//! Shell completion script generation for the six supported shells.
2	//!
3	//! Each generator walks the command tree from `cli::root()`; nothing is
4	//! pre-rendered. The scripts always refer to the crate name (`rustowl`) rather
5	//! than to `argv[0]`.
6	
7	use crate::cli::{Arg, ArgKind, Cmd};
8	
9	pub const SHELL_NAMES: &[&str] = &["bash", "elvish", "fish", "powershell", "zsh", "nushell"];
10	
11	pub fn generate(shell: &str, root: &Cmd) -> Option<String> {
12	    match shell {
13	        "bash" => Some(bash(root)),
14	        "elvish" => Some(elvish(root)),
15	        "fish" => Some(fish(root)),
16	        "powershell" => Some(powershell(root)),
17	        "zsh" => Some(zsh(root)),
18	        "nushell" => Some(nushell(root)),
19	        _ => None,
20	    }
21	}
22	
23	/// A command together with the path of names leading to it.
24	struct Node<'a> {
25	    path: Vec<&'a str>,
26	    cmd: &'a Cmd,
27	}
28	
29	/// Depth-first pre-order walk in declaration order.
30	fn walk<'a>(root: &'a Cmd) -> Vec<Node<'a>> {
31	    let mut out = Vec::new();
32	    fn rec<'a>(cmd: &'a Cmd, path: Vec<&'a str>, out: &mut Vec<Node<'a>>) {
33	        out.push(Node {
34	            path: path.clone(),
35	            cmd,
36	        });
37	        for sub in &cmd.subs {
38	            let mut p = path.clone();
39	            p.push(sub.name);
40	            rec(sub, p, out);
41	        }
42	    }
43	    rec(root, vec![root.name], &mut out);
44	    out
45	}
46	
47	fn shorts(cmd: &Cmd) -> Vec<&Arg> {
48	    cmd.args
49	        .iter()
50	        .filter(|a| !a.is_positional() && a.short.is_some())
51	        .collect()
52	}
53	
54	fn longs(cmd: &Cmd) -> Vec<&Arg> {
55	    cmd.args
56	        .iter()
57	        .filter(|a| !a.is_positional() && a.long.is_some())
58	        .collect()
59	}
60	
61	fn positionals(cmd: &Cmd) -> Vec<&Arg> {
62	    cmd.args.iter().filter(|a| a.is_positional()).collect()
63	}
64	
65	fn options(cmd: &Cmd) -> Vec<&Arg> {
66	    cmd.args.iter().filter(|a| !a.is_positional()).collect()
67	}
68	
