79	    let mut out = String::new();
80	    let fname = format!("_{}", root.name);
81	
82	    out.push_str(&format!("{fname}() {{\n"));
83	    out.push_str(
84	        "    local i cur prev opts cmd\n\
85	         \x20   COMPREPLY=()\n\
86	         \x20   if [[ \"${BASH_VERSINFO[0]}\" -ge 4 ]]; then\n\
87	         \x20       cur=\"$2\"\n\
88	         \x20   else\n\
89	         \x20       cur=\"${COMP_WORDS[COMP_CWORD]}\"\n\
90	         \x20   fi\n\
91	         \x20   prev=\"$3\"\n\
92	         \x20   cmd=\"\"\n\
93	         \x20   opts=\"\"\n\n\
94	         \x20   for i in \"${COMP_WORDS[@]:0:COMP_CWORD}\"\n\
95	         \x20   do\n\
96	         \x20       case \"${cmd},${i}\" in\n",
97	    );
98	    out.push_str(&format!(
99	        "            \",$1\")\n                cmd=\"{}\"\n                ;;\n",
100	        root.name
101	    ));
102	
103	    // Transitions, sorted by the literal case pattern.
104	    let mut transitions: Vec<(String, String)> = Vec::new();
105	    for node in &nodes {
