120	        ));
121	    }
122	    out.push_str("            *)\n                ;;\n        esac\n    done\n\n");
123	
124	    out.push_str("    case \"${cmd}\" in\n");
125	    let mut blocks: Vec<(String, &Node)> = nodes
126	        .iter()
