                let level = Level::parse(level).unwrap_or(Level::Trace);
                if module.is_empty() {
                    global = level;
                    saw_global = true;
                } else {
                    scoped.push((module.to_string(), level));
                }
            }
        }
    }
    if !saw_global && !scoped.is_empty() {
        global = Level::Off;
    }
    Filter { global, scoped }
}

fn enabled(module: &str, level: Level) -> bool {
    if level as usize > MAX_LEVEL.load(Ordering::Relaxed) {
        return false;
    }
    let filter = match FILTER.get() {
        Some(f) => f,
        None => return level <= Level::Info,
    };
    // The longest matching module directive wins.
    let mut best: Option<(usize, Level)> = None;
    for (prefix, l) in &filter.scoped {
        if module == prefix || module.starts_with(&format!("{prefix}::")) {
            let len = prefix.len();
            if best.map(|(b, _)| len > b).unwrap_or(true) {
                best = Some((len, *l));
            }
        }
    }
    let threshold = best.map(|(_, l)| l).unwrap_or(filter.global);
    level <= threshold
}

pub fn log(module: &str, level: Level, message: &str) {
    if !enabled(module, level) {
        return;
    }
    let line = format!(
        "{} {:<5} [{}] {}\n",
        timestamp(),
        level.name(),
        module,
        message
    );
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(line.as_bytes());
    let _ = lock.flush();
}

macro_rules! define_level_fn {
    ($name:ident, $level:expr) => {
        pub fn $name(module: &str, message: impl AsRef<str>) {
            log(module, $level, message.as_ref());
        }
    };
}

define_level_fn!(error, Level::Error);
define_level_fn!(warn, Level::Warn);
define_level_fn!(info, Level::Info);
define_level_fn!(debug, Level::Debug);
define_level_fn!(trace, Level::Trace);

/// RFC 3339 UTC timestamp with millisecond precision, e.g.
/// `2026-08-07T21:21:29.038Z`.
pub fn timestamp() -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let secs = now.as_secs();
    let millis = now.subsec_millis();
    let (year, month, day) = civil_from_days((secs / 86_400) as i64);
    let sod = secs % 86_400;
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z",
        year,
        month,
        day,
        sod / 3600,
        (sod % 3600) / 60,
        sod % 60,
        millis
    )
}

/// Howard Hinnant's `civil_from_days` algorithm.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

