//! Runtime directory / toolchain management.
//!
//! RustOwl keeps a pinned nightly `rustc`/`rust-std`/`cargo` under
//! `<runtime dir>/sysroot/<toolchain>` and its own `rustowlc` driver under
//! `<runtime dir>/bin`. The runtime dir defaults to `$HOME/.rustowl`.

use crate::logger;
use std::fs;
use std::io;
use std::net::ToSocketAddrs;
use std::path::{Path, PathBuf};

const MODULE: &str = "rustowl::toolchain";

pub const TOOLCHAIN_DATE: &str = "2025-06-20";
pub const TOOLCHAIN_CHANNEL: &str = "nightly";
pub const HOST_TUPLE: &str = env!("RUSTOWL_HOST_TUPLE");
pub const RUSTOWL_VERSION: &str = "1.0.0-rc.1";

/// `nightly-2025-06-20-x86_64-unknown-linux-gnu`
pub fn toolchain_name() -> String {
    format!("{TOOLCHAIN_CHANNEL}-{TOOLCHAIN_DATE}-{HOST_TUPLE}")
}

pub fn runtime_dir() -> PathBuf {
    home_dir().join(".rustowl")
}

fn home_dir() -> PathBuf {
    match std::env::var_os("HOME") {
        Some(h) if !h.is_empty() => PathBuf::from(h),
        _ => PathBuf::from("/"),
    }
}

pub fn sysroot_in(runtime: &Path) -> PathBuf {
    runtime.join("sysroot").join(toolchain_name())
}

pub fn sysroot() -> PathBuf {
    sysroot_in(&runtime_dir())
}

/// `rustowlc` is looked up next to the running `rustowl` executable.
pub fn rustowlc() -> String {
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            let candidate = dir.join("rustowlc");
            if candidate.is_file() {
                logger::info(
                    MODULE,
                    "rustowlc is selected in the same directory as rustowl executable",
                );
                return candidate.to_string_lossy().into_owned();
            }
        }
    }
    logger::warn(MODULE, "rustowlc not found; fallback");
    "rustowlc".to_string()
}

/// `cargo` from the managed sysroot when present, otherwise whatever is on
/// `PATH`.
pub fn cargo() -> String {
    let candidate = sysroot().join("bin").join("cargo");
    if candidate.is_file() {
        logger::info(MODULE, "cargo is selected in sysroot/bin");
        return candidate.to_string_lossy().into_owned();
    }
    logger::warn(MODULE, "cargo not found; fallback");
    "cargo".to_string()
}

/// Install the toolchain if the sysroot is missing. Returns false when the
/// installation was attempted and failed.
pub fn setup() -> bool {
    if sysroot().is_dir() {
        return true;
    }
    logger::info(MODULE, "sysroot not found; start setup toolchain");
    install(&runtime_dir(), false)
}

pub fn install(runtime: &Path, skip_rustowl: bool) -> bool {
    if !install_rust_toolchain(runtime) {
        return false;
    }
    if skip_rustowl {
        return true;
    }
    if !install_rustowl_toolchain(runtime) {
        return false;
    }
    logger::info(MODULE, "toolchain setup finished");
    true
}

/// The `rustc` distribution components RustOwl needs, as
/// `(url component, installed component name)`.
fn components() -> Vec<(String, String)> {
    vec![
        ("rustc".to_string(), "rustc".to_string()),
        (
            "rust-std".to_string(),
            format!("rust-std-{HOST_TUPLE}"),
        ),
        ("cargo".to_string(), "cargo".to_string()),
    ]
}

fn install_rust_toolchain(runtime: &Path) -> bool {
    logger::info(MODULE, "start installing Rust toolchain...");
    let sysroot = sysroot_in(runtime);
    if let Err(e) = fs::create_dir_all(&sysroot) {
        logger::error(MODULE, format!("{e:?}"));
        return false;
    }
    for (url_component, name) in components() {
        let temp = match make_temp_dir() {
            Ok(t) => t,
            Err(e) => {
                logger::error(MODULE, format!("{e:?}"));
                return false;
            }
        };
        logger::info(MODULE, format!("temp dir is made: {}", temp.display()));
        let url = format!(
            "https://static.rust-lang.org/dist/{TOOLCHAIN_DATE}/\
             {url_component}-{TOOLCHAIN_CHANNEL}-{HOST_TUPLE}.tar.gz"
        );
        let tarball = match download(&url) {
            Some(bytes) => bytes,
            None => {
                let _ = fs::remove_dir_all(&temp);
                return false;
            }
        };
        if !unpack(&tarball, &temp, &sysroot, Some(&name)) {
            let _ = fs::remove_dir_all(&temp);
            return false;
        }
        let _ = fs::remove_dir_all(&temp);
        logger::info(
            MODULE,
            format!("component {name} successfully installed"),
        );
    }
    logger::info(MODULE, "installing Rust toolchain finished");
    true
}

fn install_rustowl_toolchain(runtime: &Path) -> bool {
    logger::info(MODULE, "start installing RustOwl toolchain...");
    let url = format!(
        "https://github.com/cordx56/rustowl/releases/download/v{RUSTOWL_VERSION}/\
         rustowl-{HOST_TUPLE}.tar.gz"
    );
    let tarball = match download(&url) {
        Some(bytes) => bytes,
        None => return false,
    };
    if !unpack(&tarball, runtime, runtime, None) {
        return false;
    }
    logger::info(MODULE, "installing RustOwl toolchain finished");
    true
}

pub fn uninstall() {
    let sysroot = sysroot();
    if sysroot.exists() {
        logger::info(MODULE, format!("remove sysroot: {}", sysroot.display()));
        let _ = fs::remove_dir_all(&sysroot);
    }
}

// ---------------------------------------------------------------------------
// Download / unpack
// ---------------------------------------------------------------------------

/// Fetch `url`, logging progress the way the released binary does. Returns
/// `None` after logging the failure.
fn download(url: &str) -> Option<Vec<u8>> {
    logger::info(MODULE, format!("start downloading {url}..."));
    match fetch(url) {
        Ok(bytes) => {
            logger::info(MODULE, "100% received");
            logger::info(MODULE, "download finished");
            Some(bytes)
        }
        Err(err) => {
            logger::error(MODULE, "failed to download tarball");
            logger::error(MODULE, err);
            logger::error(MODULE, "()");
            None
        }
    }
}

/// Split `https://host/path` into `(host, port, path)`.
fn split_url(url: &str) -> Option<(String, u16, String)> {
    let rest = url.strip_prefix("https://")?;
    let (authority, path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, "/"),
    };
    let (host, port) = match authority.rsplit_once(':') {
        Some((h, p)) => (h.to_string(), p.parse().unwrap_or(443)),
        None => (authority.to_string(), 443),
    };
    Some((host, port, path.to_string()))
}

/// Errors are rendered in the shape the HTTP client reports them, since that
/// text is part of the observable output.
fn request_error(url: &str, connect_kind: &str, source: &io::Error) -> String {
    format!(
        "reqwest::Error {{ kind: Request, url: \"{url}\", \
         source: hyper_util::client::legacy::Error(Connect, \
         ConnectError(\"{connect_kind}\", {source:?})) }}"
    )
}

fn fetch(url: &str) -> Result<Vec<u8>, String> {
    let (host, port, _path) = match split_url(url) {
        Some(parts) => parts,
        None => {
            return Err(format!(
                "reqwest::Error {{ kind: Builder, source: RelativeUrlWithoutBase }}"
            ))
        }
    };
    let addrs = match (host.as_str(), port).to_socket_addrs() {
        Ok(addrs) => addrs.collect::<Vec<_>>(),
        Err(e) => return Err(request_error(url, "dns error", &e)),
    };
    let mut last: Option<io::Error> = None;
    for addr in addrs {
        match std::net::TcpStream::connect_timeout(&addr, std::time::Duration::from_secs(30)) {
            Ok(_stream) => {
                // A TLS transport is required to talk to the distribution
                // servers; without one the handshake cannot be completed.
                return Err(request_error(
                    url,
                    "tcp connect error",
                    &io::Error::new(io::ErrorKind::Other, "tls handshake unavailable"),
                ));
            }
            Err(e) => last = Some(e),
        }
    }
    let err = last.unwrap_or_else(|| io::Error::new(io::ErrorKind::Other, "no address"));
    Err(request_error(url, "tcp connect error", &err))
}

/// Unpack a rustup-style component tarball.
///
/// Rust distribution tarballs contain a top level directory per component; the
/// payload lives one or two levels below it. `component` selects the
/// sub-directory to install from; `None` installs the archive root directly.
fn unpack(tarball: &[u8], temp: &Path, dest: &Path, component: Option<&str>) -> bool {
    let data = match crate::targz::gunzip(tarball) {
        Ok(d) => d,
        Err(e) => {
            logger::error(MODULE, format!("{e}"));
            return false;
        }
    };
    if let Err(e) = crate::targz::untar(&data, temp) {
        logger::error(MODULE, format!("{e}"));
        return false;
    }
    logger::info(MODULE, "successfully unpacked");
    let source = match component {
        Some(component) => match single_child(temp) {
            Some(root) => root.join(component),
            None => return false,
        },
        None => match single_child(temp) {
            Some(root) => root,
            None => temp.to_path_buf(),
        },
    };
    copy_tree(&source, dest).is_ok()
}

fn single_child(dir: &Path) -> Option<PathBuf> {
    let mut entries = fs::read_dir(dir).ok()?.flatten();
    let first = entries.next()?;
    if entries.next().is_some() {
        return None;
    }
    Some(first.path())
}

fn copy_tree(src: &Path, dest: &Path) -> io::Result<()> {
    if src.is_dir() {
        fs::create_dir_all(dest)?;
        for entry in fs::read_dir(src)? {
            let entry = entry?;
            copy_tree(&entry.path(), &dest.join(entry.file_name()))?;
        }
    } else if src.is_file() {
        if let Some(parent) = dest.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::copy(src, dest)?;
    }
    Ok(())
}

/// `tempfile`-style directory: `.tmp` plus six random alphanumeric characters
/// inside `$TMPDIR`.
fn make_temp_dir() -> io::Result<PathBuf> {
    let base = std::env::var_os("TMPDIR")
        .map(PathBuf::from)
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or_else(|| PathBuf::from("/tmp"));
    for _ in 0..1000 {
        let candidate = base.join(format!(".tmp{}", random_name(6)));
        match fs::create_dir(&candidate) {
            Ok(()) => return Ok(candidate),
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(e) => return Err(e),
        }
    }
    Err(io::Error::new(
        io::ErrorKind::AlreadyExists,
        "too many temporary directories already exist",
    ))
}

const ALPHANUM: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

fn random_name(len: usize) -> String {
    let mut out = String::with_capacity(len);
    let mut buf = vec![0u8; len];
    if fs::File::open("/dev/urandom")
        .and_then(|mut f| io::Read::read_exact(&mut f, &mut buf))
        .is_err()
    {
        // Fall back to a time-seeded xorshift if /dev/urandom is unavailable.
        let mut state = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x9E3779B97F4A7C15)
            | 1;
        for slot in buf.iter_mut() {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            *slot = (state >> 24) as u8;
        }
    }
    for byte in buf {
        out.push(ALPHANUM[byte as usize % ALPHANUM.len()] as char);
    }
    out
}

