    Err(request_error(url, "tcp connect error", &err))
}

/// Unpack a rustup-style component tarball.
///
/// Rust distribution tarballs contain a top level directory per component; the
/// payload lives one or two levels below it. `component` selects the
/// sub-directory to install from; `None` installs the archive root directly.
fn unpack(tarball: &[u8], temp: &Path, dest: &Path, component: Option<&str>) -> bool {
    let data = match crate::targz::gunzip(tarball) {
        Ok(d) => d,
        Err(e) => {
            logger::error(MODULE, format!("{e}"));
            return false;
        }
    };
    if let Err(e) = crate::targz::untar(&data, temp) {
        logger::error(MODULE, format!("{e}"));
        return false;
    }
    logger::info(MODULE, "successfully unpacked");
    let source = match component {
        Some(component) => match single_child(temp) {
            Some(root) => root.join(component),
            None => return false,
        },
        None => match single_child(temp) {
            Some(root) => root,
            None => temp.to_path_buf(),
        },
    };
    copy_tree(&source, dest).is_ok()
}

fn single_child(dir: &Path) -> Option<PathBuf> {
    let mut entries = fs::read_dir(dir).ok()?.flatten();
    let first = entries.next()?;
    if entries.next().is_some() {
        return None;
    }
    Some(first.path())
}

fn copy_tree(src: &Path, dest: &Path) -> io::Result<()> {
    if src.is_dir() {
        fs::create_dir_all(dest)?;
        for entry in fs::read_dir(src)? {
            let entry = entry?;
            copy_tree(&entry.path(), &dest.join(entry.file_name()))?;
        }
    } else if src.is_file() {
        if let Some(parent) = dest.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::copy(src, dest)?;
    }
    Ok(())
}

/// `tempfile`-style directory: `.tmp` plus six random alphanumeric characters
/// inside `$TMPDIR`.
fn make_temp_dir() -> io::Result<PathBuf> {
    let base = std::env::var_os("TMPDIR")
        .map(PathBuf::from)
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or_else(|| PathBuf::from("/tmp"));
    for _ in 0..1000 {
        let candidate = base.join(format!(".tmp{}", random_name(6)));
        match fs::create_dir(&candidate) {
            Ok(()) => return Ok(candidate),
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(e) => return Err(e),
        }
    }
    Err(io::Error::new(
        io::ErrorKind::AlreadyExists,
        "too many temporary directories already exist",
    ))
}

const ALPHANUM: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

fn random_name(len: usize) -> String {
    let mut out = String::with_capacity(len);
    let mut buf = vec![0u8; len];
    if fs::File::open("/dev/urandom")
        .and_then(|mut f| io::Read::read_exact(&mut f, &mut buf))
        .is_err()
    {
        // Fall back to a time-seeded xorshift if /dev/urandom is unavailable.
        let mut state = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x9E3779B97F4A7C15)
            | 1;
        for slot in buf.iter_mut() {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            *slot = (state >> 24) as u8;
        }
    }
    for byte in buf {
        out.push(ALPHANUM[byte as usize % ALPHANUM.len()] as char);
    }
    out
}

