    out: &mut Vec<u8>,
    lit: &Huffman,
    dist: &Huffman,
) -> Result<(), String> {
    loop {
        let sym = lit.decode(reader)?;
        match sym {
            0..=255 => out.push(sym as u8),
            256 => return Ok(()),
            257..=285 => {
                let idx = sym as usize - 257;
                let len =
                    LENGTH_BASE[idx] as usize + reader.bits(LENGTH_EXTRA[idx] as u32)? as usize;
                let dsym = dist.decode(reader)? as usize;
                if dsym >= 30 {
                    return Err("invalid distance symbol".to_string());
                }
                let distance =
                    DIST_BASE[dsym] as usize + reader.bits(DIST_EXTRA[dsym] as u32)? as usize;
                if distance > out.len() {
                    return Err("distance too far back".to_string());
                }
                let start = out.len() - distance;
                for i in 0..len {
                    let b = out[start + i];
                    out.push(b);
                }
            }
            _ => return Err("invalid literal/length symbol".to_string()),
        }
    }
}

// ---------------------------------------------------------------------------
// tar
// ---------------------------------------------------------------------------

/// Extract a (ustar/gnu) tar archive into `dest`.
pub fn untar(data: &[u8], dest: &Path) -> Result<(), String> {
    let mut pos = 0usize;
    let mut long_name: Option<String> = None;
    while pos + 512 <= data.len() {
        let header = &data[pos..pos + 512];
        if header.iter().all(|&b| b == 0) {
            break;
        }
        let name = long_name.take().unwrap_or_else(|| read_str(&header[0..100]));
        let size = read_octal(&header[124..136]).unwrap_or(0) as usize;
        let typeflag = header[156];
        let mode = read_octal(&header[100..108]).unwrap_or(0o644) as u32;
        let prefix = read_str(&header[345..500]);
        let full = if prefix.is_empty() {
            name.clone()
        } else {
            format!("{prefix}/{name}")
        };
        pos += 512;
        let body_end = (pos + size).min(data.len());
        let body = &data[pos..body_end];
        pos += (size + 511) / 512 * 512;

        match typeflag {
            b'L' => {
                long_name = Some(read_str(body));
                continue;
            }
            b'K' => continue,
            _ => {}
        }
        if full.is_empty() || full.contains("..") {
            continue;
        }
        let target = dest.join(&full);
        match typeflag {
            b'5' => {
                fs::create_dir_all(&target).map_err(|e| e.to_string())?;
            }
            b'0' | b'\0' => {
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent).map_err(|e| e.to_string())?;
                }
                fs::write(&target, body).map_err(|e| e.to_string())?;
                set_mode(&target, mode);
            }
            b'2' => {
                let link = read_str(&header[157..257]);
                let _ = std::os::unix::fs::symlink(link, &target);
            }
            _ => {}
        }
    }
    Ok(())
}

fn set_mode(path: &Path, mode: u32) {
    use std::os::unix::fs::PermissionsExt;
    let _ = fs::set_permissions(path, fs::Permissions::from_mode(mode & 0o7777));
}

fn read_str(bytes: &[u8]) -> String {
    let end = bytes.iter().position(|&b| b == 0).unwrap_or(bytes.len());
    String::from_utf8_lossy(&bytes[..end]).trim().to_string()
}

fn read_octal(bytes: &[u8]) -> Option<u64> {
    let s = read_str(bytes);
    let s = s.trim();
    if s.is_empty() {
        return Some(0);
    }
    u64::from_str_radix(s, 8).ok()
}

