//! Command line parsing.
//!
//! Error and usage strings are reproduced verbatim, including the suggestion
//! ("tip:") lines which are driven by a Jaro-Winkler similarity score.

use crate::cli::{self, Arg, Cmd};

pub enum Action {
    /// Run the language server on stdin/stdout.
    Lsp,
    Version {
        quiet: usize,
    },
    Check {
        path: Option<String>,
        all_targets: bool,
        all_features: bool,
    },
    Clean,
    ToolchainInstall {
        path: Option<String>,
        skip_rustowl_toolchain: bool,
    },
    ToolchainUninstall,
    /// `toolchain` without a subcommand: nothing to do.
    Nop,
    Completions {
        shell: String,
    },
    /// Text to print on stdout, exiting successfully.
    Print(String),
}

pub struct ParseError {
    pub text: String,
}

type Res = Result<Action, ParseError>;

pub fn parse(bin: &str, argv: &[String]) -> Res {
    let root = cli::root();
    let mut p = Parser {
        bin: bin.to_string(),
        root: &root,
    };
    p.parse_root(argv)
}

struct Parser<'a> {
    bin: String,
    root: &'a Cmd,
}

/// Arguments already accepted when an error is produced; clap lists them in the
/// error's usage line.
struct UsageCtx<'a> {
    path: Vec<&'a str>,
    cmd: &'a Cmd,
    used: Vec<&'a Arg>,
}

impl<'a> Parser<'a> {
    // -- error constructors -------------------------------------------------

    fn error(&self, message: String, tip: Option<String>, usage: Option<String>, help: bool) -> ParseError {
        let mut text = format!("error: {message}\n");
        if let Some(tip) = tip {
            text.push_str(&format!("\n  tip: {tip}\n"));
        }
        if let Some(usage) = usage {
            text.push_str(&format!("\nUsage: {usage}\n"));
        }
        if help {
            text.push_str("\nFor more information, try '--help'.\n");
        }
        ParseError { text }
    }

    fn usage_of(&self, ctx: &UsageCtx) -> String {
        let mut s = self.bin.clone();
        for p in &ctx.path {
            s.push(' ');
            s.push_str(p);
        }
        if ctx.used.is_empty() {
            let full = cli::render_usage_only(&self.bin, &ctx.path, ctx.cmd);
            return full;
        }
        for a in &ctx.used {
            s.push(' ');
            s.push_str(&arg_usage_token(a));
        }
        for pos in ctx.cmd.args.iter().filter(|a| a.is_positional()) {
            s.push(' ');
            s.push_str(&positional_token(pos));
        }
        s
    }

    /// Whether the command advertises `--help`, which controls the trailing
    /// "For more information" line.
    fn has_help(cmd: &Cmd) -> bool {
        cmd.args.iter().any(|a| a.id == "help") || cmd.subs.iter().any(|c| c.name == "help")
    }

    fn unexpected_arg(&self, ctx: &mut UsageCtx<'a>, found: &str) -> ParseError {
        // A close long/short flag is suggested first; otherwise, if the command
        // accepts a positional, clap explains how to pass the token as a value.
        let names: Vec<String> = ctx
            .cmd
            .args
            .iter()
            .filter(|a| !a.is_positional())
            .filter_map(|a| a.long.map(|l| format!("--{l}")))
            .collect();
        let stripped = found.trim_start_matches('-');
        let candidates: Vec<(f64, String)> = names
            .iter()
            .map(|n| (jaro_winkler(stripped, n.trim_start_matches('-')), n.clone()))
            .filter(|(score, _)| *score > 0.7)
            .collect();
        let best = pick_best(&candidates);
        let tip = match &best {
            Some(name) => Some(format!("a similar argument exists: '{name}'")),
            None => {
                if ctx.cmd.args.iter().any(|a| a.is_positional()) {
                    Some(format!("to pass '{found}' as a value, use '-- {found}'"))
                } else {
                    None
                }
            }
        };
        if let Some(name) = &best {
            if let Some(arg) = ctx
                .cmd
                .args
                .iter()
                .find(|a| a.long.map(|l| format!("--{l}")) == Some(name.clone()))
            {
                ctx.used.push(arg);
            }
        }
        let usage = self.usage_of(ctx);
        self.error(
            format!("unexpected argument '{found}' found"),
            tip,
            Some(usage),
            Self::has_help(ctx.cmd),
        )
    }

    fn unrecognized_subcommand(
        &self,
        ctx: &UsageCtx<'a>,
        found: &str,
        suggest: bool,
    ) -> ParseError {
        let tip = if suggest {
            let names: Vec<&str> = ctx.cmd.subs.iter().map(|c| c.name).collect();
            let mut candidates: Vec<(f64, String)> = names
                .iter()
                .map(|n| (jaro_winkler(found, n), n.to_string()))
                .filter(|(score, _)| *score > 0.7)
                .collect();
            // clap orders suggestions by ascending score.
            candidates.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
            match candidates.len() {
                0 => None,
                1 => Some(format!(
                    "a similar subcommand exists: '{}'",
                    candidates[0].1
                )),
                _ => Some(format!(
                    "some similar subcommands exist: {}",
                    candidates
                        .iter()
                        .map(|(_, n)| format!("'{n}'"))
                        .collect::<Vec<_>>()
                        .join(", ")
                )),
            }
        } else {
            None
        };
        let usage = self.usage_of(ctx);
        self.error(
            format!("unrecognized subcommand '{found}'"),
            tip,
            Some(usage),
            Self::has_help(ctx.cmd),
        )
    }

    // -- parsing ------------------------------------------------------------

    fn parse_root(&mut self, argv: &[String]) -> Res {
        let root = self.root;
        let mut ctx = UsageCtx {
            path: Vec::new(),
            cmd: root,
            used: Vec::new(),
        };
        let mut quiet = 0usize;
        let mut version = false;
        let mut escaped = false;
        let mut i = 0;
        while i < argv.len() {
            let arg = &argv[i];
            i += 1;
            if !escaped && arg == "--" {
                escaped = true;
                continue;
            }
            if !escaped && arg.starts_with("--") {
                let (name, value) = split_long(arg);
                match name {
                    "help" => {
                        if value.is_some() {
                            return Err(self.unexpected_value(&mut ctx, "--help", value.unwrap()));
                        }
                        return Ok(Action::Print(cli::render_help(&self.bin, &[], root, true)));
                    }
                    "version" => {
                        if value.is_some() {
                            return Err(self.unexpected_value(
                                &mut ctx,
                                "--version",
                                value.unwrap(),
                            ));
                        }
                        if version {
                            return Err(self.multiple_times(&mut ctx, "--version"));
                        }
                        version = true;
                        ctx.used.push(find_arg(root, "version"));
                    }
                    "quiet" => {
                        if value.is_some() {
                            return Err(self.unexpected_value(
                                &mut ctx,
                                "--quiet...",
                                value.unwrap(),
                            ));
                        }
                        quiet += 1;
                    }
                    "stdio" => {
                        if value.is_some() {
                            return Err(self.unexpected_value(&mut ctx, "--stdio", value.unwrap()));
                        }
                    }
                    _ => return Err(self.unexpected_arg(&mut ctx, name_with_dashes(arg))),
                }
                continue;
            }
            if !escaped && arg.len() > 1 && arg.starts_with('-') {
                for c in arg[1..].chars() {
                    match c {
                        'h' => {
                            return Ok(Action::Print(cli::render_help(&self.bin, &[], root, false)))
                        }
                        'V' => {
                            if version {
                                return Err(self.multiple_times(&mut ctx, "--version"));
                            }
                            version = true;
                            ctx.used.push(find_arg(root, "version"));
                        }
                        'q' => quiet += 1,
                        other => {
                            return Err(self.unexpected_arg(&mut ctx, &format!("-{other}")));
                        }
                    }
                }
                continue;
            }
            // Subcommand or stray positional.
            if let Some(sub) = root.find_sub(arg) {
                if escaped {
                    let tip = format!(
                        "subcommand '{arg}' exists; to use it, remove the '--' before it"
                    );
                    let usage = self.usage_of(&ctx);
                    return Err(self.error(
                        format!("unexpected argument '{arg}' found"),
                        Some(tip),
                        Some(usage),
                        true,
                    ));
                }
                return self.parse_sub(sub, &argv[i..], quiet);
            }
            return Err(self.unrecognized_subcommand(&ctx, arg, true));
        }
        if version {
            return Ok(Action::Version { quiet });
        }
        Ok(Action::Lsp)
    }

    fn unexpected_value(&self, ctx: &mut UsageCtx<'a>, arg: &str, value: &str) -> ParseError {
        let long = arg.trim_start_matches('-').trim_end_matches('.');
        if let Some(found) = ctx
            .cmd
            .args
            .iter()
            .find(|a| a.long == Some(long))
        {
            ctx.used.push(found);
        }
        let usage = self.usage_of(ctx);
        self.error(
            format!("unexpected value '{value}' for '{arg}' found; no more were expected"),
            None,
            Some(usage),
            Self::has_help(ctx.cmd),
        )
    }

    fn multiple_times(&self, ctx: &mut UsageCtx<'a>, arg: &str) -> ParseError {
        let usage = cli::render_usage_only(&self.bin, &ctx.path, ctx.cmd);
        self.error(
            format!("the argument '{arg}' cannot be used multiple times"),
            None,
            Some(usage),
            Self::has_help(ctx.cmd),
        )
    }

    fn parse_sub(&mut self, cmd: &'a Cmd, rest: &[String], _quiet: usize) -> Res {
        match cmd.name {
            "check" => self.parse_check(cmd, rest),
            "clean" => self.parse_simple(cmd, rest, Action::Clean),
            "toolchain" => self.parse_toolchain(cmd, rest),
            "completions" => self.parse_completions(cmd, rest),
            "help" => self.parse_help(rest),
            _ => unreachable!(),
        }
    }

    /// A command with no arguments beyond `-h/--help`.
    fn parse_simple(&mut self, cmd: &'a Cmd, rest: &[String], action: Action) -> Res {
        let path = vec![cmd.name];
        let mut ctx = UsageCtx {
            path: path.clone(),
            cmd,
            used: Vec::new(),
        };
        let mut escaped = false;
        for arg in rest {
            if !escaped && arg == "--" {
                escaped = true;
                continue;
            }
            if !escaped {
                if let Some(help) = self.help_flag(arg, cmd, &path, &mut ctx)? {
                    return Ok(help);
                }
            }
            return Err(self.unexpected_arg(&mut ctx, arg));
        }
        Ok(action)
    }

    /// Recognise `-h`/`--help` for `cmd`; returns the rendered help.
    fn help_flag(
        &self,
        arg: &str,
        cmd: &'a Cmd,
        path: &[&'a str],
        ctx: &mut UsageCtx<'a>,
    ) -> Result<Option<Action>, ParseError> {
        if arg == "--help" {
            return Ok(Some(Action::Print(cli::render_help(
                &self.bin, path, cmd, true,
            ))));
        }
        if arg == "-h" {
            return Ok(Some(Action::Print(cli::render_help(
                &self.bin, path, cmd, false,
            ))));
        }
        if let Some(value) = arg.strip_prefix("--help=") {
            return Err(self.unexpected_value(ctx, "--help", value));
        }
        Ok(None)
    }

    fn parse_check(&mut self, cmd: &'a Cmd, rest: &[String]) -> Res {
        let path_names = vec![cmd.name];
        let mut ctx = UsageCtx {
            path: path_names.clone(),
            cmd,
            used: Vec::new(),
        };
        let mut all_targets = false;
        let mut all_features = false;
        let mut target: Option<String> = None;
        let mut escaped = false;
        for arg in rest {
            if !escaped && arg == "--" {
                escaped = true;
                continue;
            }
            if !escaped && arg.starts_with("--") {
                let (name, value) = split_long(arg);
                match name {
                    "help" => {
                        if let Some(v) = value {
                            return Err(self.unexpected_value(&mut ctx, "--help", v));
                        }
                        return Ok(Action::Print(cli::render_help(
                            &self.bin,
                            &path_names,
                            cmd,
                            true,
                        )));
                    }
                    "all-targets" => {
                        if let Some(v) = value {
                            return Err(self.unexpected_value(&mut ctx, "--all-targets", v));
                        }
                        if all_targets {
                            return Err(self.multiple_times(&mut ctx, "--all-targets"));
                        }
                        all_targets = true;
                        ctx.used.push(find_arg(cmd, "all_targets"));
                    }
                    "all-features" => {
                        if let Some(v) = value {
                            return Err(self.unexpected_value(&mut ctx, "--all-features", v));
                        }
                        if all_features {
                            return Err(self.multiple_times(&mut ctx, "--all-features"));
                        }
                        all_features = true;
                        ctx.used.push(find_arg(cmd, "all_features"));
                    }
                    _ => return Err(self.unexpected_arg(&mut ctx, name_with_dashes(arg))),
                }
                continue;
            }
            if !escaped && arg.len() > 1 && arg.starts_with('-') {
                if arg == "-h" {
                    return Ok(Action::Print(cli::render_help(
                        &self.bin,
                        &path_names,
                        cmd,
                        false,
                    )));
                }
                return Err(self.unexpected_arg(&mut ctx, arg));
            }
            if target.is_none() {
                target = Some(arg.clone());
            } else {
                return Err(self.unexpected_arg(&mut ctx, arg));
            }
        }
        Ok(Action::Check {
            path: target,
            all_targets,
            all_features,
        })
    }

    fn parse_toolchain(&mut self, cmd: &'a Cmd, rest: &[String]) -> Res {
        let path_names = vec![cmd.name];
        let mut ctx = UsageCtx {
            path: path_names.clone(),
            cmd,
            used: Vec::new(),
        };
        let mut escaped = false;
        for (i, arg) in rest.iter().enumerate() {
            if !escaped && arg == "--" {
                escaped = true;
                continue;
            }
            if !escaped {
                if let Some(help) = self.help_flag(arg, cmd, &path_names, &mut ctx)? {
                    return Ok(help);
                }
                if arg.starts_with('-') && arg.len() > 1 {
                    return Err(self.unexpected_arg(&mut ctx, name_with_dashes(arg)));
                }
            }
            return match cmd.find_sub(arg) {
                Some(sub) if sub.name == "install" => {
                    self.parse_install(sub, &rest[i + 1..])
                }
                Some(sub) if sub.name == "uninstall" => {
                    self.parse_simple_at(sub, &rest[i + 1..], &["toolchain", "uninstall"], Action::ToolchainUninstall)
                }
                Some(sub) if sub.name == "help" => {
                    self.parse_help_at(cmd, &rest[i + 1..], &["toolchain"])
                }
                _ => Err(self.unrecognized_subcommand(&ctx, arg, true)),
            };
        }
        Ok(Action::Nop)
    }

    fn parse_simple_at(
        &mut self,
        cmd: &'a Cmd,
        rest: &[String],
        path: &[&'a str],
        action: Action,
    ) -> Res {
        let mut ctx = UsageCtx {
            path: path.to_vec(),
            cmd,
            used: Vec::new(),
        };
        let mut escaped = false;
        for arg in rest {
            if !escaped && arg == "--" {
                escaped = true;
                continue;
            }
            if !escaped {
                if let Some(help) = self.help_flag(arg, cmd, path, &mut ctx)? {
                    return Ok(help);
                }
            }
            return Err(self.unexpected_arg(&mut ctx, arg));
        }
        Ok(action)
    }

    fn parse_install(&mut self, cmd: &'a Cmd, rest: &[String]) -> Res {
        let path_names = vec!["toolchain", "install"];
        let mut ctx = UsageCtx {
            path: path_names.clone(),
            cmd,
            used: Vec::new(),
        };
        let mut install_path: Option<String> = None;
        let mut skip = false;
        let mut escaped = false;
        let mut i = 0;
        while i < rest.len() {
            let arg = &rest[i];
            i += 1;
            if !escaped && arg == "--" {
                escaped = true;
                continue;
            }
            if !escaped && arg.starts_with("--") {
                let (name, value) = split_long(arg);
                match name {
                    "help" => {
                        if let Some(v) = value {
                            return Err(self.unexpected_value(&mut ctx, "--help", v));
                        }
                        return Ok(Action::Print(cli::render_help(
                            &self.bin,
                            &path_names,
                            cmd,
                            true,
                        )));
                    }
                    "path" => match value {
                        Some(v) => install_path = Some(v.to_string()),
                        None => match rest.get(i) {
                            Some(v) => {
                                install_path = Some(v.clone());
                                i += 1;
                            }
                            None => {
                                return Err(self.error(
                                    "a value is required for '--path <path>' but none was supplied"
                                        .to_string(),
                                    None,
                                    None,
                                    true,
                                ))
                            }
                        },
                    },
                    "skip-rustowl-toolchain" => {
                        if let Some(v) = value {
                            return Err(self.unexpected_value(
                                &mut ctx,
                                "--skip-rustowl-toolchain",
                                v,
                            ));
                        }
                        if skip {
                            return Err(
                                self.multiple_times(&mut ctx, "--skip-rustowl-toolchain")
                            );
                        }
                        skip = true;
                        ctx.used.push(find_arg(cmd, "skip_rustowl_toolchain"));
                    }
                    _ => return Err(self.unexpected_arg(&mut ctx, name_with_dashes(arg))),
                }
                continue;
            }
            if !escaped && arg == "-h" {
                return Ok(Action::Print(cli::render_help(
                    &self.bin,
                    &path_names,
                    cmd,
                    false,
                )));
            }
            return Err(self.unexpected_arg(&mut ctx, arg));
        }
        Ok(Action::ToolchainInstall {
            path: install_path,
            skip_rustowl_toolchain: skip,
        })
    }

    fn parse_completions(&mut self, cmd: &'a Cmd, rest: &[String]) -> Res {
        let path_names = vec![cmd.name];
        let mut ctx = UsageCtx {
            path: path_names.clone(),
            cmd,
            used: Vec::new(),
        };
        let mut shell: Option<String> = None;
        let mut escaped = false;
        for arg in rest {
            if !escaped && arg == "--" {
                escaped = true;
                continue;
            }
            if !escaped {
                if let Some(help) = self.help_flag(arg, cmd, &path_names, &mut ctx)? {
                    return Ok(help);
                }
                if arg.starts_with('-') && arg.len() > 1 {
                    return Err(self.unexpected_arg(&mut ctx, name_with_dashes(arg)));
                }
            }
            if shell.is_none() {
                shell = Some(arg.clone());
            } else {
                return Err(self.unexpected_arg(&mut ctx, arg));
            }
        }
        let shell = match shell {
            Some(s) => s,
            None => {
                let usage = cli::render_usage_only(&self.bin, &path_names, cmd);
                return Err(self.error(
                    "the following required arguments were not provided:\n  <SHELL>".to_string(),
                    None,
                    Some(usage),
                    true,
                ));
            }
        };
        if !cli::SHELLS.iter().any(|(v, _)| *v == shell) {
            let values: Vec<&str> = cli::SHELLS.iter().map(|(v, _)| *v).collect();
            let candidates: Vec<(f64, String)> = values
                .iter()
                .map(|v| (jaro_winkler(&shell, v), v.to_string()))
                .filter(|(score, _)| *score > 0.7)
                .collect();
            let tip = pick_best(&candidates)
                .map(|best| format!("a similar value exists: '{best}'"));
            return Err(self.error(
                format!(
                    "invalid value '{shell}' for '<SHELL>'\n  [possible values: {}]",
                    values.join(", ")
                ),
                tip,
                None,
                true,
            ));
        }
        Ok(Action::Completions { shell })
    }

    fn parse_help(&mut self, rest: &[String]) -> Res {
        self.parse_help_at(self.root, rest, &[])
    }

    /// `help [SUBCOMMAND]...`: walk the requested chain and print its help.
    fn parse_help_at(&mut self, start: &'a Cmd, rest: &[String], prefix: &[&'a str]) -> Res {
        let mut cmd = start;
        let mut path: Vec<&str> = prefix.to_vec();
        for arg in rest {
            match cmd.find_sub(arg) {
                Some(sub) => {
                    // `help help` documents the help command itself.
                    cmd = sub;
                    path.push(sub.name);
                }
                None => {
                    let usage = cli::render_usage_only(&self.bin, &path, cmd);
                    return Err(self.error(
                        format!("unrecognized subcommand '{arg}'"),
                        None,
                        Some(usage),
                        Self::has_help(cmd),
                    ));
                }
            }
        }
        Ok(Action::Print(cli::render_help(
            &self.bin,
            &path,
            cmd,
            true,
        )))
    }
}

fn find_arg<'a>(cmd: &'a Cmd, id: &str) -> &'a Arg {
    cmd.args.iter().find(|a| a.id == id).expect("known arg")
}

fn arg_usage_token(a: &Arg) -> String {
    let mut s = String::new();
    match a.long {
        Some(l) => {
            s.push_str("--");
            s.push_str(l);
        }
        None => {
            if let Some(c) = a.short {
                s.push('-');
                s.push(c);
            }
        }
    }
    if a.multiple {
        s.push_str("...");
    }
    if a.takes_value() {
        s.push_str(&format!(" <{}>", a.value_name));
    }
    s
}

fn positional_token(a: &Arg) -> String {
    if a.required {
        format!("<{}>", a.value_name)
    } else {
        format!("[{}]", a.value_name)
    }
}

/// `--name=value` -> `("name", Some("value"))`
fn split_long(arg: &str) -> (&str, Option<&str>) {
    let body = &arg[2..];
    match body.split_once('=') {
        Some((n, v)) => (n, Some(v)),
        None => (body, None),
    }
}

/// The token as the user typed it, with the `=value` part removed.
fn name_with_dashes(arg: &str) -> &str {
    match arg.find('=') {
        Some(i) => &arg[..i],
        None => arg,
    }
}

/// Highest-scoring candidate, matching clap's "take the best match" behaviour.
fn pick_best(candidates: &[(f64, String)]) -> Option<String> {
    let mut sorted: Vec<&(f64, String)> = candidates.iter().collect();
    sorted.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    sorted.last().map(|(_, n)| n.clone())
}

// ---------------------------------------------------------------------------
// Jaro-Winkler similarity (used for the suggestion tips)
// ---------------------------------------------------------------------------

pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro = jaro(a, b);
    if jaro <= 0.7 {
        return jaro;
    }
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let prefix = a
        .iter()
        .zip(b.iter())
        .take(4)
        .take_while(|(x, y)| x == y)
        .count();
    jaro + 0.1 * prefix as f64 * (1.0 - jaro)
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let window = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_match = vec![false; a.len()];
    let mut b_match = vec![false; b.len()];
    let mut matches = 0usize;
    for (i, ca) in a.iter().enumerate() {
        let start = i.saturating_sub(window);
        let end = (i + window + 1).min(b.len());
        for j in start..end {
            if !b_match[j] && b[j] == *ca {
                a_match[i] = true;
                b_match[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if !a_match[i] {
            continue;
        }
        while !b_match[k] {
            k += 1;
        }
        if a[i] != b[k] {
            transpositions += 1;
        }
        k += 1;
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - transpositions as f64 / 2.0) / m) / 3.0
}

